/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Call, Handler
 *   Functions: receipt, mount, optionTexts, saveButton, read, chooseFirst, overlap
 *   Constants: pairingPath, routes, heading, first, second, firstOptions, outcome, save, saveRefused,
 *              saveUnknown, chooseRefused, chooseUnknown
 * Tests
 *   - the panel reads the release's rows and lists each track with its duration and only the tracks it can pair with, closest first with the difference
 *   - a track every pairing gives the same release track starts on it and says so; the others start empty and Save waits for them
 *   - a track without a duration lists every release track without a difference, and equal durations read as the same
 *   - a release track another track chose is disabled and named as used until it is freed
 *   - saving sends every track's Disc and Track Number with its saved base, an unchanged one included, then reads the lookup and chooses the release
 *   - a re-rank that already applied this release or another of its editions through a pairing needs no choice, while one applied for its Album values only is chosen again
 *   - a save that leaves the tracks pairing in more than one way chooses nothing and says the numbers are saved but the release was not used
 *   - an unconfirmed save says so and is sent again as the same operation by Save; a refused save says it was not saved, keeps the choices and starts a new one after reading the review again
 *   - a choice that fails after the save keeps the numbers and offers Use this release, which chooses without saving again: an unconfirmed one as the same operation, a refused one as a new one
 *   - a read that fails says so with Try again, and a read for another run saves nothing
 *   - Cancel closes without a request; a disabled panel disables choosing and saving but keeps Cancel, and a running save disables every control
 *   - a reload request says to reload and leaves only Cancel; Cancel after an unconfirmed save has the page read the review again
 *   - a track whose review captured no Disc Number saves its Track Number alone
 * @end-catalog */

import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { deferred, reviewId, reviewJson, session, slotId, slotTwo, viewer } from './catalogReviewFixtures.testSupport';
import { handPairingResponse, pairedLookupResponse, pairingApplication, pairingEditions, pairingLookupResponse } from './catalogReviewLookupFixtures.testSupport';
import { CandidatePairing } from './CandidatePairing';
import styles from './adminStyles';

/**
 * The pairing panel on its own, its reads and changes answered per method and path: the release's rows and each track's options
 * closest first, forced rows, duplicate prevention, the save-then-choose sequence, its failures and retries, a stale read and
 * Cancel. All names and identifiers are synthetic.
 */
type Call = { method: string; path: string; body: Record<string, unknown> | undefined };
type Handler = (body: Record<string, unknown> | undefined, count: number) => Response | Promise<Response>;
const pairingPath = `/catalog-reviews/${reviewId}/lookup/candidates/${encodeURIComponent(pairingEditions[0])}/pairing`;
const routes = { read: `GET ${pairingPath}`, save: `PATCH /catalog-reviews/${reviewId}`, lookup: `GET /catalog-reviews/${reviewId}/lookup`, choose: `POST /catalog-reviews/${reviewId}/lookup/choose` };
/** A change's answer: the review at `revision` and the receipt of the request's own operation. */
const receipt = (body: Record<string, unknown> | undefined, revision: number) => reviewJson({ item: { id: reviewId, revision }, receipt: { operationId: body?.operationId } });
const heading = 'Pair the tracks with "Synthetic Live Album 2" (20 tracks on 2 discs)';
const first = '1 · Synthetic opening (Live) · 3:35.66', second = '2 · Synthetic second song (Live) · 6:22.75';
const firstOptions = ['Choose a release track', '1-1 Synthetic live song 1 · 3:35.64 · differs by 0.02 s', '2-2 Synthetic live song 14 · 3:34.95 · differs by 0.71 s'];
const outcome = 'Saving stores these Disc and Track Numbers in the completion draft as your own values, then uses this release, which brings in its expected tracklist, with 18 rows without a file, and track details. The original Album changes only when you confirm Update original Album.';
const save = 'Save pairing and use this release';
const saveRefused = 'The Disc and Track Numbers were not saved, so this release was not used. Try again.';
const saveUnknown = 'Saving the Disc and Track Numbers did not complete or could not be confirmed. Try again; a repeated save is applied only once.';
const chooseRefused = 'The Disc and Track Numbers are saved, but this release is not in use yet. Use it below.';
const chooseUnknown = 'The Disc and Track Numbers are saved, but using this release did not complete or could not be confirmed. Use it below; a repeated choice is applied only once.';

/** Mounts the panel for the live release's first edition at run 3; each route answers through its handler, anything else 500. */
function mount(handlers: Partial<Record<keyof typeof routes, Handler>>, props: { disabled?: boolean } = {}) {
  const calls: Call[] = [], counts = new Map<string, number>();
  const fetch = vi.fn(async (input: string, init: RequestInit = {}) => {
    const method = init.method ?? 'GET', path = String(input).replace(/^\/api\/admin\/v1/, ''), body = init.body ? JSON.parse(String(init.body)) as Record<string, unknown> : undefined;
    calls.push({ method, path, body });
    const name = (Object.keys(routes) as (keyof typeof routes)[]).find(key => routes[key] === `${method} ${path}`), count = (counts.get(`${method} ${path}`) ?? 0) + 1;
    counts.set(`${method} ${path}`, count);
    return name && handlers[name] ? handlers[name]!(body, count) : reviewJson({ code: 'unexpected' }, 500);
  });
  vi.stubGlobal('fetch', fetch);
  const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session);
  const invalidate = vi.spyOn(client, 'invalidateQueries'), onBusy = vi.fn(), onClose = vi.fn();
  const element = (disabled: boolean) => <QueryClientProvider client={client}><CandidatePairing projectId={reviewId} candidateKey={pairingEditions[0]} editions={pairingEditions}
    run={3} title="Synthetic Live Album 2" disabled={disabled} onBusy={onBusy} onClose={onClose} /></QueryClientProvider>;
  const view = render(element(props.disabled ?? false));
  const { epoch, generation } = adminWorkspace.getSnapshot();
  return { calls, invalidate, onBusy, onClose, reviewKey: ['admin-catalog-reviews', viewer, epoch, generation, reviewId], rerender: (disabled: boolean) => view.rerender(element(disabled)),
    writes: () => calls.filter(call => call.method !== 'GET'), requests: () => calls.map(call => `${call.method} ${call.path}`) };
}
const optionTexts = (name: string) => within(screen.getByRole('combobox', { name })).getAllByRole('option').map(option => option.textContent);
const saveButton = () => screen.getByRole('button', { name: save });
/** Answers a read with the live release's pairing read at `revision`. */
const read = (revision = 1): Handler => () => reviewJson(handPairingResponse(revision));
/** Chooses the first track's closer release track and waits until saving is possible. */
async function chooseFirst() {
  fireEvent.change(await screen.findByRole('combobox', { name: first }), { target: { value: '1:1' } });
  await waitFor(() => expect(saveButton()).toBeEnabled());
}
beforeEach(() => {
  adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true }); adminWorkspace.select('admin');
});
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); vi.restoreAllMocks(); });

test('the panel reads the release\'s rows and lists each track with its duration and only the tracks it can pair with, closest first with the difference', async () => {
  const { requests } = mount({ read: read() });
  const title = screen.getByRole('heading', { name: 'Pair tracks by hand' });
  expect(document.activeElement).toBe(title);
  expect(screen.getByRole('status')).toHaveTextContent('Loading…');
  expect(await screen.findByRole('heading', { name: heading })).toBe(title);
  expect(document.activeElement).toBe(title);
  expect(screen.getByRole('region', { name: heading })).toBeInTheDocument();
  expect(screen.getByText(/^For each track of this Album, choose which track of this release it is\./)).toBeInTheDocument();
  expect(optionTexts(first)).toEqual(firstOptions);
  expect(optionTexts(second)).toEqual(['Choose a release track', '1-2 Synthetic live song 2 · 6:22.75 · differs by 0.01 s']);
  expect(screen.getByText(outcome)).toBeInTheDocument();
  expect(requests()).toEqual([routes.read]);
});

test('a track every pairing gives the same release track starts on it and says so; the others start empty and Save waits for them', async () => {
  mount({ read: read() });
  const two = await screen.findByRole('combobox', { name: second }), one = screen.getByRole('combobox', { name: first });
  expect(two).toHaveValue('1:2');
  expect(two).toHaveAccessibleDescription('Only 1-2 "Synthetic live song 2" can pair with this track');
  expect(one).toHaveValue(''); expect(one).not.toHaveAccessibleDescription();
  expect(screen.getByText('1 track still needs a release track.')).toBeInTheDocument();
  expect(saveButton()).toBeDisabled(); expect(saveButton()).toHaveClass(styles.primary);
  fireEvent.change(one, { target: { value: '1:1' } });
  expect(saveButton()).toBeEnabled();
  expect(screen.queryByText(/still needs? a release track/)).not.toBeInTheDocument();
  // Choosing none again makes Save wait once more.
  fireEvent.change(one, { target: { value: '' } });
  expect(saveButton()).toBeDisabled();
});

/** Three tracks over three release tracks: two of them close to both of the first two, one without a duration. */
const overlap = () => ({ run: 3, revision: 1, rows: [{ disc: 1, track: 1, title: 'Synthetic row one', durationMs: 200_000 }, { disc: 1, track: 2, title: 'Synthetic row two', durationMs: 201_000 },
  { disc: 1, track: 3, title: 'Synthetic row three', durationMs: null }], members: [
  { slotId, title: 'Synthetic near', durationMs: 200_004, saved: { disc: null, track: null }, discSavable: true, options: [{ disc: 1, track: 1, deltaMs: 4 }, { disc: 1, track: 2, deltaMs: 996 }], forced: null },
  { slotId: slotTwo, title: 'Synthetic far', durationMs: 200_900, saved: { disc: null, track: null }, discSavable: true, options: [{ disc: 1, track: 2, deltaMs: 100 }, { disc: 1, track: 1, deltaMs: 900 }], forced: null },
  { slotId: '10000000-0000-4000-8000-000000000003', title: '', durationMs: null, saved: { disc: null, track: null }, discSavable: true,
    options: [{ disc: 1, track: 1, deltaMs: null }, { disc: 1, track: 2, deltaMs: null }, { disc: 1, track: 3, deltaMs: null }], forced: null }] });

