  mount({ read: () => reviewJson(overlap()) });
  await screen.findByRole('combobox', { name: '1 · Synthetic near · 3:20.00' });
  expect(optionTexts('1 · Synthetic near · 3:20.00')).toEqual(['Choose a release track', '1-1 Synthetic row one · 3:20.00 · same duration', '1-2 Synthetic row two · 3:21.00 · differs by 1.00 s']);
  expect(optionTexts('2 · Synthetic far · 3:20.90')).toEqual(['Choose a release track', '1-2 Synthetic row two · 3:21.00 · differs by 0.10 s', '1-1 Synthetic row one · 3:20.00 · differs by 0.90 s']);
  expect(optionTexts('3 · — · duration unknown')).toEqual(['Choose a release track', '1-1 Synthetic row one · 3:20.00', '1-2 Synthetic row two · 3:21.00', '1-3 Synthetic row three · duration unknown']);
  expect(screen.getByText(/^Saving stores these Disc and Track Numbers in the completion draft as your own values, then uses this release, which brings in its expected tracklist and track details\./)).toBeInTheDocument();
