test('a release track another track chose is disabled and named as used until it is freed', async () => {
  mount({ read: () => reviewJson(overlap()) });
  const near = await screen.findByRole('combobox', { name: '1 · Synthetic near · 3:20.00' });
  const option = (name: string, text: RegExp) => within(screen.getByRole('combobox', { name })).getByRole('option', { name: text }) as HTMLOptionElement;
  fireEvent.change(near, { target: { value: '1:1' } });
  for (const name of ['2 · Synthetic far · 3:20.90', '3 · — · duration unknown']) {
    expect(option(name, /^1-1 /)).toBeDisabled();
    expect(option(name, /^1-1 /).textContent).toMatch(/ · used by track 1$/);
    expect(option(name, /^1-2 /)).toBeEnabled();
  }
  expect(option('1 · Synthetic near · 3:20.00', /^1-1 /)).toBeEnabled();
  fireEvent.change(near, { target: { value: '1:2' } });
  for (const name of ['2 · Synthetic far · 3:20.90', '3 · — · duration unknown']) {
    expect(option(name, /^1-1 /)).toBeEnabled(); expect(option(name, /^1-1 /).textContent).not.toMatch(/used by/);
    expect(option(name, /^1-2 /)).toBeDisabled(); expect(option(name, /^1-2 /).textContent).toMatch(/ · used by track 1$/);
  }
});

test('saving sends every track\'s Disc and Track Number with its saved base, an unchanged one included, then reads the lookup and chooses the release', async () => {
  const saved = deferred<Response>(), looked = deferred<Response>();
  const { invalidate, onBusy, onClose, reviewKey, requests, writes } = mount({ read: read(), save: () => saved.promise, lookup: () => looked.promise,
    choose: body => receipt(body, 3) });
  await chooseFirst();
  fireEvent.click(saveButton());
  expect(await screen.findByText('Saving the Disc and Track Numbers…')).toHaveAttribute('role', 'status');
  expect(onBusy).toHaveBeenLastCalledWith(true);
  for (const control of [...screen.getAllByRole('combobox'), ...screen.getAllByRole('button')]) expect(control).toBeDisabled();
  const patch = writes()[0].body!;
  expect(patch).toEqual({ expectedRevision: 1, operationId: expect.any(String), changes: [
    { path: `tracks.${slotId}.discNumber`, base: null, value: 1 }, { path: `tracks.${slotId}.trackNumber`, base: null, value: 1 },
    { path: `tracks.${slotTwo}.discNumber`, base: null, value: 1 }, { path: `tracks.${slotTwo}.trackNumber`, base: null, value: 2 }] });
  await act(async () => { saved.resolve(receipt(patch, 2)); });
  expect(await screen.findByText('Using this release…')).toBeInTheDocument();
  await act(async () => { looked.resolve(reviewJson(pairedLookupResponse())); });
  await waitFor(() => expect(onClose).toHaveBeenCalledTimes(1));
  expect(requests()).toEqual([routes.read, routes.save, routes.lookup, routes.choose]);
  const chosen = writes()[1].body!;
  expect(chosen).toEqual({ expectedRevision: 2, run: 3, candidateKey: pairingEditions[0], operationId: expect.any(String) });
  expect(chosen.operationId).not.toBe(patch.operationId);
  expect(onBusy.mock.calls).toEqual([[true], [false]]);
  // The chooser is idle again before the panel closes as used, so focus can move on.
  expect(onClose).toHaveBeenCalledWith(true);
  expect(onBusy.mock.invocationCallOrder[1]).toBeLessThan(onClose.mock.invocationCallOrder[0]);
  // The review is read again, but not this panel's own read, as it closes.
  expect(invalidate).toHaveBeenCalledTimes(1);
  const [{ queryKey, predicate }] = invalidate.mock.calls[0] as unknown as [{ queryKey: unknown[]; predicate: (query: { queryKey: unknown[] }) => boolean }];
  expect(queryKey).toEqual(reviewKey);
  expect([predicate({ queryKey: [...reviewKey] }), predicate({ queryKey: [...reviewKey, 'lookup', 2] }), predicate({ queryKey: [...reviewKey, 'pairing', pairingEditions[0], 3] })])
    .toEqual([true, true, false]);
  cleanup();
  // A track whose saved numbers already equal its choice still sends them, so they become the administrator's own.
  const forced = handPairingResponse();
  forced.members[1].saved = { disc: 1, track: 2 };
  const again = mount({ read: () => reviewJson(forced), save: body => receipt(body, 2), lookup: () => reviewJson(pairedLookupResponse()), choose: body => receipt(body, 3) });
  await chooseFirst();
  fireEvent.click(saveButton());
  await waitFor(() => expect(again.onClose).toHaveBeenCalledTimes(1));
  expect((again.writes()[0].body!.changes as unknown[]).slice(2)).toEqual([{ path: `tracks.${slotTwo}.discNumber`, base: 1, value: 1 }, { path: `tracks.${slotTwo}.trackNumber`, base: 2, value: 2 }]);
});

test('a re-rank that already applied this release or another of its editions through a pairing needs no choice, while one applied for its Album values only is chosen again', async () => {
  const applied = mount({ read: read(), save: body => receipt(body, 2), lookup: () => reviewJson(pairedLookupResponse(pairingApplication(pairingEditions[1], true))) });
  await chooseFirst();
  fireEvent.click(saveButton());
  await waitFor(() => expect(applied.onClose).toHaveBeenCalledTimes(1));
  expect(applied.requests().filter(request => request !== routes.read)).toEqual([routes.save, routes.lookup]);
  cleanup();
  const albumOnly = mount({ read: read(), save: body => receipt(body, 2), lookup: () => reviewJson(pairedLookupResponse(pairingApplication(pairingEditions[0], false))), choose: body => receipt(body, 3) });
  await chooseFirst();
  fireEvent.click(saveButton());
  await waitFor(() => expect(albumOnly.onClose).toHaveBeenCalledTimes(1));
  expect(albumOnly.requests().filter(request => request !== routes.read)).toEqual([routes.save, routes.lookup, routes.choose]);
  cleanup();
  // An application of this release through another pairing (2-2 for the first track) is not this one, so it is chosen again.
  const other = pairingApplication(pairingEditions[0], true);
  other.pairs = [{ slotId, discNumber: 2, trackNumber: 2 }, { slotId: slotTwo, discNumber: 1, trackNumber: 2 }];
  const elsewhere = mount({ read: read(), save: body => receipt(body, 2), lookup: () => reviewJson(pairedLookupResponse(other)), choose: body => receipt(body, 3) });
  await chooseFirst();
  fireEvent.click(saveButton());
  await waitFor(() => expect(elsewhere.onClose).toHaveBeenCalledTimes(1));
  expect(elsewhere.requests().filter(request => request !== routes.read).at(-1)).toBe(routes.choose);
});

test('a save that leaves the tracks pairing in more than one way chooses nothing and says the numbers are saved but the release was not used', async () => {
  const { invalidate, onClose, reviewKey, requests } = mount({ read: read(), save: body => receipt(body, 2), lookup: () => reviewJson(pairingLookupResponse()) });
  await chooseFirst();
  fireEvent.click(saveButton());
  expect(await screen.findByText('The Disc and Track Numbers are saved, but in the latest lookup result the tracks do not pair with this release in exactly one way, so it was not used. Check the latest result.'))
    .toHaveAttribute('role', 'status');
  expect(requests().filter(request => request !== routes.read)).toEqual([routes.save, routes.lookup]);
  expect(invalidate).toHaveBeenCalledWith({ queryKey: reviewKey });
  expect(onClose).not.toHaveBeenCalled();
});

test('an unconfirmed save says so and is sent again as the same operation by Save; a refused save says it was not saved, keeps the choices and starts a new one after reading the review again', async () => {
  const lost = mount({ read: read(), save: (body, count) => count === 1 ? Promise.reject(new TypeError('Failed to fetch')) : receipt(body, 2),
    lookup: () => reviewJson(pairedLookupResponse()), choose: body => receipt(body, 3) });
  await chooseFirst();
  fireEvent.click(saveButton());
  expect(await screen.findByText(saveUnknown)).toHaveAttribute('role', 'status');
  expect(screen.queryByText(saveRefused)).not.toBeInTheDocument();
  expect(lost.invalidate).not.toHaveBeenCalled();
  expect(screen.getByRole('combobox', { name: first })).toHaveValue('1:1');
  fireEvent.click(saveButton());
  await waitFor(() => expect(lost.onClose).toHaveBeenCalledTimes(1));
  const [failed, replayed] = lost.writes();
  expect(replayed.body).toEqual(failed.body);
  cleanup();
  const refused = mount({ read: (_body, count) => reviewJson(handPairingResponse(count === 1 ? 1 : 5)),
    save: (body, count) => count === 1 ? reviewJson({ code: 'ADMIN_IMPORT_FIELD_CONFLICT' }, 409) : receipt(body, 6),
    lookup: () => reviewJson(pairedLookupResponse()), choose: body => receipt(body, 7) });
  await chooseFirst();
  fireEvent.click(saveButton());
  expect(await screen.findByText(saveRefused)).toBeInTheDocument();
  expect(refused.invalidate).toHaveBeenCalledWith({ queryKey: refused.reviewKey });
  await waitFor(() => expect(refused.requests().filter(request => request === routes.read)).toHaveLength(2));
  expect(screen.getByRole('combobox', { name: first })).toHaveValue('1:1');
  await waitFor(() => expect(saveButton()).toBeEnabled());
  fireEvent.click(saveButton());
  await waitFor(() => expect(refused.onClose).toHaveBeenCalledTimes(1));
  const [rejected, fresh] = refused.writes();
  expect(fresh.body!.operationId).not.toBe(rejected.body!.operationId);
  expect([rejected.body!.expectedRevision, fresh.body!.expectedRevision]).toEqual([1, 5]);
  expect(fresh.body!.changes).toEqual(rejected.body!.changes);
});

test('a choice that fails after the save keeps the numbers and offers Use this release, which chooses without saving again: an unconfirmed one as the same operation, a refused one as a new one', async () => {
  const { onClose, writes, requests } = mount({ read: (_body, count) => reviewJson(handPairingResponse(count === 1 ? 1 : 2)), save: body => receipt(body, 2),
    lookup: () => reviewJson(pairedLookupResponse()),
    choose: (body, count) => count === 1 ? reviewJson({ code: 'ADMIN_CATALOG_REVIEW_UNAVAILABLE' }, 503) : count === 2 ? reviewJson({ code: 'ADMIN_IMPORT_LOOKUP_STALE' }, 409) : receipt(body, 3) });
  await chooseFirst();
  fireEvent.click(saveButton());
  expect(await screen.findByText(chooseUnknown)).toHaveAttribute('role', 'status');
  expect(screen.queryByRole('button', { name: save })).not.toBeInTheDocument();
  const use = screen.getByRole('button', { name: 'Use this release' });
  expect(use).toHaveClass(styles.primary);
  await waitFor(() => expect(use).toBeEnabled());
  fireEvent.click(use);
  await waitFor(() => expect(writes()).toHaveLength(3));
  const [, unconfirmed, replayed] = writes();
  expect(replayed.body).toEqual(unconfirmed.body);
  // A refused choice says the release is not in use and starts a new operation at the review revision read again.
  expect(await screen.findByText(chooseRefused)).toHaveAttribute('role', 'status');
  await waitFor(() => expect(screen.getByRole('button', { name: 'Use this release' })).toBeEnabled());
  fireEvent.click(screen.getByRole('button', { name: 'Use this release' }));
  await waitFor(() => expect(onClose).toHaveBeenCalledTimes(1));
  const last = writes().at(-1)!;
  expect(last.body).toEqual({ expectedRevision: 2, run: 3, candidateKey: pairingEditions[0], operationId: expect.any(String) });
  expect(last.body!.operationId).not.toBe(replayed.body!.operationId);
  expect(requests().filter(request => request === routes.save)).toHaveLength(1);
});

test('a read that fails says so with Try again, and a read for another run saves nothing', async () => {
  for (const [status, code] of [[500, 'ADMIN_CATALOG_REVIEW_UNAVAILABLE'], [404, 'ADMIN_CATALOG_REVIEW_NOT_FOUND'], [409, 'ADMIN_IMPORT_LOOKUP_CANDIDATE_INCOMPLETE']] as const) {
    const { requests } = mount({ read: (_body, count) => count === 1 ? reviewJson({ code }, status) : reviewJson(handPairingResponse()) });
    expect(await screen.findByRole('alert')).toHaveTextContent("This release's tracks could not be loaded. Try again, or cancel and check the latest lookup result.");
    expect(screen.queryByRole('combobox')).not.toBeInTheDocument();
    fireEvent.click(screen.getByRole('button', { name: 'Try again' }));
    expect(await screen.findByRole('combobox', { name: first })).toBeInTheDocument();
    expect(requests()).toEqual([routes.read, routes.read]);
    cleanup();
  }
  const { onClose, writes } = mount({ read: () => reviewJson({ ...handPairingResponse(), run: 4 }) });
  expect(await screen.findByText('The lookup changed since you opened it. Review its latest result and choose again.')).toBeInTheDocument();
  expect(screen.queryByRole('combobox')).not.toBeInTheDocument();
  expect(screen.queryByRole('button', { name: save })).not.toBeInTheDocument();
  fireEvent.click(screen.getByRole('button', { name: 'Cancel' }));
  expect([onClose.mock.calls.length, writes()]).toEqual([1, []]);
});

test('Cancel closes without a request; a disabled panel disables choosing and saving but keeps Cancel, and a running save disables every control', async () => {
  const { invalidate, onClose, requests, rerender } = mount({ read: read(), save: () => new Promise<Response>(() => {}) });
  await chooseFirst();
  fireEvent.click(screen.getByRole('button', { name: 'Cancel' }));
  expect(onClose.mock.calls).toEqual([[false]]);
  expect(requests()).toEqual([routes.read]);
  expect(invalidate).not.toHaveBeenCalled();
  // While the chooser is disabled nothing can be chosen or saved; closing the panel stays possible.
  rerender(true);
  for (const control of [...screen.getAllByRole('combobox'), saveButton()]) expect(control).toBeDisabled();
  expect(screen.getByRole('button', { name: 'Cancel' })).toBeEnabled();
  rerender(false);
  await waitFor(() => expect(saveButton()).toBeEnabled());
  fireEvent.click(saveButton());
  await screen.findByText('Saving the Disc and Track Numbers…');
  for (const control of [...screen.getAllByRole('combobox'), ...screen.getAllByRole('button')]) expect(control).toBeDisabled();
});

test('a reload request says to reload and leaves only Cancel; Cancel after an unconfirmed save has the page read the review again', async () => {
  const reloading = mount({ read: read(), save: () => reviewJson({ code: 'ADMIN_IMPORT_RELOAD_REQUIRED' }, 409) });
  await chooseFirst();
  fireEvent.click(saveButton());
  expect(await screen.findByText('The administrator workbench was updated. Reload the page to continue; unsaved edits on this page are not kept.')).toHaveAttribute('role', 'status');
  await waitFor(() => expect(reloading.onBusy).toHaveBeenLastCalledWith(false));
  for (const control of [...screen.getAllByRole('combobox'), saveButton()]) expect(control).toBeDisabled();
  expect(screen.getByRole('button', { name: 'Cancel' })).toBeEnabled();
  expect(reloading.writes()).toHaveLength(1);
  cleanup();
  const lost = mount({ read: read(), save: () => reviewJson({ code: 'ADMIN_CATALOG_REVIEW_UNAVAILABLE' }, 503) });
  await chooseFirst();
  fireEvent.click(saveButton());
  await screen.findByText(saveUnknown);
  expect(lost.invalidate).not.toHaveBeenCalled();
  fireEvent.click(screen.getByRole('button', { name: 'Cancel' }));
  expect(lost.onClose.mock.calls).toEqual([[false]]);
  expect(lost.invalidate).toHaveBeenCalledTimes(1);
  expect((lost.invalidate.mock.calls[0][0] as { queryKey: unknown[] }).queryKey).toEqual(lost.reviewKey);
});

test('a track whose review captured no Disc Number saves its Track Number alone', async () => {
  const legacy = handPairingResponse();
  legacy.members[0].discSavable = false;
  const { onClose, writes } = mount({ read: () => reviewJson(legacy), save: body => receipt(body, 2), lookup: () => reviewJson(pairedLookupResponse()), choose: body => receipt(body, 3) });
  await chooseFirst();
  fireEvent.click(saveButton());
  await waitFor(() => expect(onClose).toHaveBeenCalledWith(true));
  expect(writes()[0].body!.changes).toEqual([{ path: `tracks.${slotId}.trackNumber`, base: null, value: 1 },
    { path: `tracks.${slotTwo}.discNumber`, base: null, value: 1 }, { path: `tracks.${slotTwo}.trackNumber`, base: null, value: 2 }]);
});
